"3157 :   static boolean isExpressionResultUsed(Node expr) {
3158 :     // TODO(johnlenz): consider sharing some code with trySimpleUnusedResult.
3159 :     Node parent = expr.getParent();
3160 :     switch (parent.getType()) {
3161 :       case Token.BLOCK:
3162 :       case Token.EXPR_RESULT:
3163 :         return false;
3164 :       case Token.CAST:
3165 :         return isExpressionResultUsed(parent);
3166 :       case Token.HOOK:
3167 :       case Token.AND:
3168 :       case Token.OR:
3169 :         return (expr == parent.getFirstChild())
3170 :             ? true : isExpressionResultUsed(parent);
3171 :       case Token.COMMA:
3172 :         Node gramps = parent.getParent();
3173 :         if (gramps.isCall() &&
3174 :             parent == gramps.getFirstChild()) {
3175 :           // Semantically, a direct call to eval is different from an indirect
3176 :           // call to an eval. See ECMA-262 S15.1.2.1. So it's OK for the first
3177 :           // expression to a comma to be a no-op if it's used to indirect
3178 :           // an eval. This we pretend that this is "used".
3179 :           if (expr == parent.getFirstChild() &&
3180 :               parent.getChildCount() == 2 &&
3181 :               expr.getNext().isName() &&
3182 :               "eval".equals(expr.getNext().getString())) {
3183 :             return true;
3184 :           }
3185 :         }
3186 : 
3187 :         return (expr == parent.getFirstChild())
3188 :             ? false : isExpressionResultUsed(parent);
3189 :       case Token.FOR:
3190 :         if (!NodeUtil.isForIn(parent)) {
3191 :           // Only an expression whose result is in the condition part of the
3192 :           // expression is used.
3193 :           return (parent.getChildAtIndex(1) == expr);
3194 :         }
3195 :         break;
3196 :     }
3197 :     return true;
3198 :   }"

