"351 :   @Override
352 :   protected List<PassFactory> getOptimizations() {
353 :     List<PassFactory> passes = Lists.newArrayList();
354 :     passes.add(garbageCollectChecks);
355 : 
356 :     // TODO(nicksantos): The order of these passes makes no sense, and needs
357 :     // to be re-arranged.
358 : 
359 :     if (options.runtimeTypeCheck) {
360 :       passes.add(runtimeTypeCheck);
361 :     }
362 : 
363 :     passes.add(createEmptyPass("beforeStandardOptimizations"));
364 : 
365 :     if (options.replaceIdGenerators) {
366 :       passes.add(replaceIdGenerators);
367 :     }
368 : 
369 :     // Optimizes references to the arguments variable.
370 :     if (options.optimizeArgumentsArray) {
371 :       passes.add(optimizeArgumentsArray);
372 :     }
373 : 
374 :     // Abstract method removal works best on minimally modified code, and also
375 :     // only needs to run once.
376 :     if (options.closurePass &&
377 :         (options.removeAbstractMethods || options.removeClosureAsserts)) {
378 :       passes.add(closureCodeRemoval);
379 :     }
380 : 
381 :     // Collapsing properties can undo constant inlining, so we do this before
382 :     // the main optimization loop.
383 :     if (options.collapseProperties) {
384 :       passes.add(collapseProperties);
385 :     }
386 : 
387 :     // ReplaceStrings runs after CollapseProperties in order to simplify
388 :     // pulling in values of constants defined in enums structures.
389 :     if (!options.replaceStringsFunctionDescriptions.isEmpty()) {
390 :       passes.add(replaceStrings);
391 :     }
392 : 
393 :     // Tighten types based on actual usage.
394 :     if (options.tightenTypes) {
395 :       passes.add(tightenTypesBuilder);
396 :     }
397 : 
398 :     // Property disambiguation should only run once and needs to be done
399 :     // soon after type checking, both so that it can make use of type
400 :     // information and so that other passes can take advantage of the renamed
401 :     // properties.
402 :     if (options.disambiguateProperties) {
403 :       passes.add(disambiguateProperties);
404 :     }
405 : 
406 :     if (options.computeFunctionSideEffects) {
407 :       passes.add(markPureFunctions);
408 :     } else if (options.markNoSideEffectCalls) {
409 :       // TODO(user) The properties that this pass adds to CALL and NEW
410 :       // AST nodes increase the AST's in-memory size.  Given that we are
411 :       // already running close to our memory limits, we could run into
412 :       // trouble if we end up using the @nosideeffects annotation a lot
413 :       // or compute @nosideeffects annotations by looking at function
414 :       // bodies.  It should be easy to propagate @nosideeffects
415 :       // annotations as part of passes that depend on this property and
416 :       // store the result outside the AST (which would allow garbage
417 :       // collection once the pass is done).
418 :       passes.add(markNoSideEffectCalls);
419 :     }
420 : 
421 :     if (options.chainCalls) {
422 :       passes.add(chainCalls);
423 :     }
424 : 
425 :     // Constant checking must be done after property collapsing because
426 :     // property collapsing can introduce new constants (e.g. enum values).
427 :     // TODO(johnlenz): make checkConsts namespace aware so it can be run
428 :     // as during the checks phase.
429 :     passes.add(checkConsts);
430 : 
431 :     // The Caja library adds properties to Object.prototype, which breaks
432 :     // most for-in loops.  This adds a check to each loop that skips
433 :     // any property matching /___$/.
434 :     if (options.ignoreCajaProperties) {
435 :       passes.add(ignoreCajaProperties);
436 :     }
437 : 
438 :     assertAllOneTimePasses(passes);
439 : 
440 :     if (options.smartNameRemoval || options.reportPath != null) {
441 :       passes.addAll(getCodeRemovingPasses());
442 :       passes.add(smartNamePass);
443 :     }
444 : 
445 :     // This needs to come after the inline constants pass, which is run within
446 :     // the code removing passes.
447 :     if (options.closurePass) {
448 :       passes.add(closureOptimizePrimitives);
449 :     }
450 : 
451 :     // TODO(user): This forces a first crack at crossModuleCodeMotion
452 :     // before devirtualization. Once certain functions are devirtualized,
453 :     // it confuses crossModuleCodeMotion ability to recognized that
454 :     // it is recursive.
455 : 
456 :     // TODO(user): This is meant for a temporary quick win.
457 :     // In the future, we might want to improve our analysis in
458 :     // CrossModuleCodeMotion so we don't need to do this.
459 :     if (options.crossModuleCodeMotion) {
460 :       passes.add(crossModuleCodeMotion);
461 :     }
462 : 
463 :     // Method devirtualization benefits from property disambiguation so
464 :     // it should run after that pass but before passes that do
465 :     // optimizations based on global names (like cross module code motion
466 :     // and inline functions).  Smart Name Removal does better if run before
467 :     // this pass.
468 :     if (options.devirtualizePrototypeMethods) {
469 :       passes.add(devirtualizePrototypeMethods);
470 :     }
471 : 
472 :     if (options.customPasses != null) {
473 :       passes.add(getCustomPasses(
474 :           CustomPassExecutionTime.BEFORE_OPTIMIZATION_LOOP));
475 :     }
476 : 
477 :     passes.add(createEmptyPass("beforeMainOptimizations"));
478 : 
479 :     passes.addAll(getMainOptimizationLoop());
480 : 
481 :     if (options.specializeInitialModule) {
482 :       // When specializing the initial module, we want our fixups to be
483 :       // as lean as possible, so we run the entire optimization loop to a
484 :       // fixed point before specializing, then specialize, and then run the
485 :       // main optimization loop again.
486 : 
487 :       if (options.crossModuleCodeMotion) {
488 :         passes.add(crossModuleCodeMotion);
489 :       }
490 : 
491 :       if (options.crossModuleMethodMotion) {
492 :         passes.add(crossModuleMethodMotion);
493 :       }
494 : 
495 :       passes.add(specializeInitialModule);
496 :       passes.addAll(getMainOptimizationLoop());
497 :     }
498 : 
499 :     passes.add(createEmptyPass("beforeModuleMotion"));
500 : 
501 :     if (options.crossModuleCodeMotion) {
502 :       passes.add(crossModuleCodeMotion);
503 :     }
504 : 
505 :     if (options.crossModuleMethodMotion) {
506 :       passes.add(crossModuleMethodMotion);
507 :     }
508 : 
509 :     passes.add(createEmptyPass("afterModuleMotion"));
510 : 
511 :     // Some optimizations belong outside the loop because running them more
512 :     // than once would either have no benefit or be incorrect.
513 :     if (options.customPasses != null) {
514 :       passes.add(getCustomPasses(
515 :           CustomPassExecutionTime.AFTER_OPTIMIZATION_LOOP));
516 :     }
517 : 
518 :     if (options.flowSensitiveInlineVariables) {
519 :       passes.add(flowSensitiveInlineVariables);
520 : 
521 :       // After inlining some of the variable uses, some variables are unused.
522 :       // Re-run remove unused vars to clean it up.
523 :       if (options.removeUnusedVars || options.removeUnusedLocalVars) {
524 :         passes.add(removeUnusedVars);
525 :       }
526 :     }
527 : 
528 :     // Running this pass again is required to have goog.events compile down to
529 :     // nothing when compiled on its own.
530 :     if (options.smartNameRemoval) {
531 :       passes.add(smartNamePass2);
532 :     }
533 : 
534 :     if (options.collapseAnonymousFunctions) {
535 :       passes.add(collapseAnonymousFunctions);
536 :     }
537 : 
538 :     // Move functions before extracting prototype member declarations.
539 :     if (options.moveFunctionDeclarations ||
540 :         // renamePrefixNamescape relies on moveFunctionDeclarations
541 :         // to preserve semantics.
542 :         options.renamePrefixNamespace != null) {
543 :       passes.add(moveFunctionDeclarations);
544 :     }
545 : 
546 :     if (options.anonymousFunctionNaming ==
547 :         AnonymousFunctionNamingPolicy.MAPPED) {
548 :       passes.add(nameMappedAnonymousFunctions);
549 :     }
550 : 
551 :     // The mapped name anonymous function pass makes use of information that
552 :     // the extract prototype member declarations pass removes so the former
553 :     // happens before the latter.
554 :     //
555 :     // Extracting prototype properties screws up the heuristic renaming
556 :     // policies, so never run it when those policies are requested.
557 :     if (options.extractPrototypeMemberDeclarations &&
558 :         (options.propertyRenaming != PropertyRenamingPolicy.HEURISTIC &&
559 :          options.propertyRenaming !=
560 :             PropertyRenamingPolicy.AGGRESSIVE_HEURISTIC)) {
561 :       passes.add(extractPrototypeMemberDeclarations);
562 :     }
563 : 
564 :     if (options.ambiguateProperties &&
565 :         (options.propertyRenaming == PropertyRenamingPolicy.ALL_UNQUOTED)) {
566 :       passes.add(ambiguateProperties);
567 :     }
568 : 
569 :     if (options.propertyRenaming != PropertyRenamingPolicy.OFF) {
570 :       passes.add(renameProperties);
571 :     }
572 : 
573 :     // Reserve global names added to the "windows" object.
574 :     if (options.reserveRawExports) {
575 :       passes.add(gatherRawExports);
576 :     }
577 : 
578 :     // This comes after property renaming because quoted property names must
579 :     // not be renamed.
580 :     if (options.convertToDottedProperties) {
581 :       passes.add(convertToDottedProperties);
582 :     }
583 : 
584 :     // Property renaming must happen before this pass runs since this
585 :     // pass may convert dotted properties into quoted properties.  It
586 :     // is beneficial to run before alias strings, alias keywords and
587 :     // variable renaming.
588 :     if (options.rewriteFunctionExpressions) {
589 :       passes.add(rewriteFunctionExpressions);
590 :     }
591 : 
592 :     // This comes after converting quoted property accesses to dotted property
593 :     // accesses in order to avoid aliasing property names.
594 :     if (!options.aliasableStrings.isEmpty() || options.aliasAllStrings) {
595 :       passes.add(aliasStrings);
596 :     }
597 : 
598 :     if (options.aliasExternals) {
599 :       passes.add(aliasExternals);
600 :     }
601 : 
602 :     if (options.aliasKeywords) {
603 :       passes.add(aliasKeywords);
604 :     }
605 : 
606 :     // Passes after this point can no longer depend on normalized AST
607 :     // assumptions.
608 :     passes.add(markUnnormalized);
609 : 
610 :     if (options.coalesceVariableNames) {
611 :       passes.add(coalesceVariableNames);
612 : 
613 :       // coalesceVariables creates identity assignments and more redundant code
614 :       // that can be removed, rerun the peephole optimizations to clean them
615 :       // up.
616 :       if (options.foldConstants) {
617 :         passes.add(peepholeOptimizations);
618 :       }
619 :     }
620 : 
621 :     if (options.collapseVariableDeclarations) {
622 :       passes.add(exploitAssign);
623 :       passes.add(collapseVariableDeclarations);
624 :     }
625 : 
626 :     // This pass works best after collapseVariableDeclarations.
627 :     passes.add(denormalize);
628 : 
629 :     if (options.instrumentationTemplate != null) {
630 :       passes.add(instrumentFunctions);
631 :     }
632 : 
633 :     if (options.variableRenaming != VariableRenamingPolicy.ALL) {
634 :       // If we're leaving some (or all) variables with their old names,
635 :       // then we need to undo any of the markers we added for distinguishing
636 :       // local variables ("$$1").
637 :       passes.add(invertContextualRenaming);
638 :     }
639 : 
640 :     if (options.variableRenaming != VariableRenamingPolicy.OFF) {
641 :       passes.add(renameVars);
642 :     }
643 : 
644 :     if (options.groupVariableDeclarations) {
645 :       passes.add(groupVariableDeclarations);
646 :     }
647 : 
648 :     // This pass should run after names stop changing.
649 :     if (options.processObjectPropertyString) {
650 :       passes.add(objectPropertyStringPostprocess);
651 :     }
652 : 
653 :     if (options.labelRenaming) {
654 :       passes.add(renameLabels);
655 :     }
656 : 
657 :     if (options.foldConstants) {
658 :       passes.add(latePeepholeOptimizations);
659 :     }
660 : 
661 :     if (options.anonymousFunctionNaming ==
662 :         AnonymousFunctionNamingPolicy.UNMAPPED) {
663 :       passes.add(nameUnmappedAnonymousFunctions);
664 :     }
665 : 
666 :     passes.add(stripSideEffectProtection);
667 : 
668 :     if (options.renamePrefixNamespace != null) {
669 :       if (!GLOBAL_SYMBOL_NAMESPACE_PATTERN.matcher(
670 :           options.renamePrefixNamespace).matches()) {
671 :         throw new IllegalArgumentException(
672 :             "Illegal character in renamePrefixNamespace name: "
673 :             + options.renamePrefixNamespace);
674 :       }
675 :       passes.add(rescopeGlobalSymbols);
676 :     }
677 : 
678 :     // Safety checks
679 :     passes.add(sanityCheckAst);
680 :     passes.add(sanityCheckVars);
681 : 
682 :     return passes;
683 :   }"

